	/* Only run action if the device is on the specified domain */
	if (dev->pm != NULL) {
		for (int i = 0; i < dev->pm->domain_count; i++) {
			if (dev->pm->domains[i] == visitor_context->domain) {
				(void)pm_device_action_run(dev,
						visitor_context->action);
				break;
			}
		}
	}

	return 0;
